def collect(path):
    out = []
    for name in repo.list(path):
        full = path + "/" + name[:-1] if name.endswith("/") else path + "/" + name
        if name.endswith("/"):
            out.extend(collect(full))
        elif name.endswith(".txt"):
            out.append(full)
    return out

files = sorted(collect("data"))
if not files:
    result({"files": [], "total": 0, "note": "no .txt files under data/"})
else:
    r = env.run(["wc", "-l"] + files, check=False)
    result({"files": files, "wc_exit": r.code, "wc_stdout": r.stdout, "wc_stderr": r.stderr})
